def stat_row(stats):
    return '<div class="case-stats">'+''.join(f'<div><strong>{v}</strong><span>{l}</span></div>' for v,l in stats)+'</div>'

def evidence_links(items):
    return '<div class="source-box"><p class="eyebrow">INSPECT THE EVIDENCE</p>'+''.join(ext(url,label) for label,url in items)+'</div>'

def case(p, subtitle, intro, stats,sections,sources, nextid, nextname):
    toc=''.join(f'<a href="#{sid}">{title}</a>' for sid,title,_ in sections)
    prose=''.join(f'<section id="{sid}"><h2>{title}</h2>{content}</section>' for sid,title,content in sections)
    body=f'''<section class="case-hero shell"><a class="back-link" href="/projects/">← All work</a>{eyebrow(p['category'])}<h1>{subtitle}</h1><p class="lead">{intro}</p><div class="case-hero-links">{ext(p['repo'],'Explore repository','button')}{link('#evidence','Evidence & decisions','text-link')}</div>{stat_row(stats)}</section><section class="shell case-visual">{p['visual']}</section><div class="shell case-layout"><aside class="case-toc"><p class="eyebrow">IN THIS CASE STUDY</p>{toc}<a href="#evidence">Sources</a></aside><article class="prose case-prose">{prose}<section id="evidence"><h2>Source, results and decisions</h2>{evidence_links(sources)}</section></article></div><section class="shell next-project"><span>NEXT CASE STUDY</span><a href="/projects/{nextid}/">{nextname} {ARROW}</a></section>'''
    page('/projects/'+p['id']+'/',p['name'],intro,body,'case-page')

case(PROJECTS[0],'Make a large pipeline<br><em>small enough to recover.</em>','REES46 V2 connects historical shopping events to a recommendation benchmark and a local API. The most useful engineering happened when the aggregation failed.',[('411.7M','Bronze events processed'),('410.3M','canonical Silver events'),('5,000','held-out ranking test users')],[
('problem','The problem', '<p>I wanted to build the path from messy event logs to usable recommendations. That meant ingestion, data checks, deduplication, features, model comparison and a serving boundary, rather than starting with a clean notebook table.</p>'),
('failure','Two failures, two constraints','<p>The first global Gold aggregation attempted to group roughly 410 million Silver events. DuckDB spilled about 30.6 GiB and exhausted the temporary-disk limit. I changed the pipeline to process one month at a time.</p><p>That fixed ordinary grouped facts, but ordered session <code>list()</code> aggregation still exhausted memory on November’s data. Its aggregate state could not be offloaded in the same way.</p><p>I streamed each month into <strong>64 deterministic hash buckets on <code>user_session</code></strong>, aggregated one bucket at a time using a single DuckDB thread, then streamed the completed outputs into the monthly Parquet file. A session stays in one bucket, preserving its event order. Completed atomic outputs are reused on restart.</p>'),
('pipeline','The data foundation','<p>Bronze processed <strong>411,709,736</strong> events from October 2019 to April 2020. Deduplication removed <strong>1,384,422</strong> exact duplicates, leaving <strong>410,325,314</strong> canonical Silver events. Monthly Gold builds user-item, item, user and category-affinity facts, plus session sequences.</p><p>The model side includes popularity, co-visitation, collaborative retrieval, hybrid retrieval and purchase ranking. A TensorFlow sequence model is retained as an experiment. MLflow records the experiments, and FastAPI exposes the selected bundle locally with a popularity fallback for unknown users.</p>'),
('evaluation','A separate, bounded benchmark','<p>The ranking benchmark used <strong>1,499,021 training interactions</strong>, 50,000 training sessions, 5,000 validation users and <strong>5,000 held-out test users</strong>. Training covered October–February, validation March and final testing April. These sample sizes are separate from the full event-processing corpus.</p><div class="table-scroll"><table><caption>April 2020 offline ranking benchmark · higher is better</caption><thead><tr><th scope="col">Metric</th><th scope="col">Popularity</th><th scope="col">Purchase ranker</th></tr></thead><tbody><tr><th scope="row">MRR@20</th><td>0.02443</td><td>0.03556</td></tr><tr><th scope="row">Recall@10</th><td>0.05685</td><td>0.07087</td></tr><tr><th scope="row">NDCG@20</th><td>0.03593</td><td>0.04429</td></tr></tbody></table></div><p>Absolute ranking quality is modest. This is an offline result; it does not measure online engagement, revenue or users served by a production service.</p>'),
('next','What I would test next','<p>I would investigate candidate recall, cold-start handling and realistic latency and memory benchmarks before treating this as a deployed recommendation service. Freshness, online experimentation and continuous retraining remain future work.</p>')
],[('Aggregation ADR',GH+'/rees46-v2/blob/main/docs/adr/001-partitioned-gold.md'),('Data foundation JSON',GH+'/rees46-v2/blob/main/results/data_foundation.json'),('Frozen ranking benchmark',GH+'/rees46-v2/blob/main/results/latest/model_benchmark.json'),('Source and reproduction guide',GH+'/rees46-v2')],'fulfillai','FulfillAI')

case(PROJECTS[1],'Build the service.<br><em>Then practise recovery.</em>','FulfillAI starts with synthetic operational data and extends into a controlled GCP/GKE API delivery lab. It is a place to learn the connections between data, models and infrastructure.',[('50K','synthetic orders'),('69.59%','test WAPE · still high'),('GKE','controlled API delivery lab')],[
('data','Before the model','<p>I generated a deterministic fulfillment dataset with 50,000 synthetic orders, 300 products and five warehouses. PostgreSQL and dbt organize the relational data and features. Redpanda / PySpark explore streaming; MLflow and FastAPI provide experiment tracking and a service boundary.</p>'),
('metrics','The result and the trade-off','<p>On <strong>63,501 synthetic test rows</strong>, a hard-gated two-stage hurdle forecast reduced WAPE from <strong>88.24% to 69.59%</strong> against the rolling-28 baseline. The relative reduction is 21.14%, but the remaining error is substantial.</p><div class="table-scroll"><table><caption>Frozen synthetic demand benchmark · lower is better</caption><thead><tr><th scope="col">Metric</th><th scope="col">Rolling-28 baseline</th><th scope="col">Hurdle model</th></tr></thead><tbody><tr><th scope="row">WAPE</th><td>88.24%</td><td>69.59%</td></tr><tr><th scope="row">RMSE</th><td>0.836723</td><td>0.933770</td></tr></tbody></table></div><p>RMSE got worse. I kept both measures visible because improvement on one metric was not enough to call the model broadly better. Model choices and thresholds were frozen before the final chronological test.</p>'),
('delivery','Build and promotion have an owner','<p>Terraform provisions the GCP infrastructure. GitHub Actions validates source and infrastructure, builds and scans the container, authenticates with OIDC / Workload Identity Federation, and promotes the exact image digest into Git-backed desired state.</p><p><strong>Actions owns build and promotion. Argo CD owns deployment.</strong> Argo CD reconciles the Helm-managed API on GKE. That separation mattered when I worked through field-ownership and rollout-verification problems.</p>'),
('recovery','A deliberate bad release','<p>I introduced a nonexistent image. Kubernetes reported <code>ErrImagePull</code> and <code>ImagePullBackOff</code>, while existing healthy replicas continued serving. I checked the events, restored a known-good revision, verified recovery and restored Argo CD self-healing after the exercise.</p><p>The observability path includes Prometheus, Grafana, Alertmanager and an end-to-end synthetic alert to Slack. The <strong>99.9% SLO is a lab target</strong> used by alert rules, rather than achieved historical uptime.</p>'),
('boundaries','What the evidence actually covers','<p>The recorded cloud checks cover API health, metrics, delivery and recovery. They do not establish that every model artifact or the entire PostgreSQL/dbt/streaming stack was exercised in GKE.</p><p>Detailed HPA, PDB and RBAC exercises were performed in a separate local kind lab. NetworkPolicy objects and selectors were checked, but packet-level enforcement was not proved. There is no claim of customer traffic or professional on-call ownership.</p><p>The most complete implementation remains on <code>platform-engineering-v2</code>. The default branch links to it.</p>')
],[('Platform V2 overview',GH+'/fulfillai/blob/platform-engineering-v2/docs/cloudops/V2_OVERVIEW.md'),('Successful delivery run',GH+'/fulfillai/actions/runs/37233814366'),('Frozen model results',GH+'/fulfillai/blob/platform-engineering-v2/results/frozen_metrics_v1.0.0.json'),('Bad-release incident record',GH+'/fulfillai/blob/platform-engineering-v2/incidents/INC-002-bad-release.md')],'otto','OTTO forecasting')

rankings=list(csv.DictReader((ROOT/'evidence/otto-ranking.csv').read_text().splitlines()))
ranking_table='<div class="table-scroll"><table><caption>All eight methods · mean development CV WAPE · lower is better</caption><thead><tr><th scope="col">Method</th><th scope="col">WAPE</th></tr></thead><tbody>'+''.join(f'<tr><th scope="row">{r["model"]}</th><td>{float(r["mean_cv_wape"])*100:.2f}%</td></tr>' for r in rankings)+'</tbody></table></div>'
case(PROJECTS[2],'Keep the result.<br><em>Even when it surprises you.</em>','My MSc dissertation compares forecasting approaches on aggregate hourly OTTO cart and order activity. The weekly seasonal baseline won the predefined development comparison.',[('672','hourly observations'),('8','model approaches'),('96h','separate final holdout')],[
('question','A large log, a short series','<p>After aggregating OTTO event logs, I had 672 consecutive hourly observations: about four weeks. The task is to use 168 hours of history to forecast 24 hourly cart and order counts. Product identifiers are deliberately excluded, so this is <strong>aggregate activity forecasting</strong>.</p>'),
('protocol','Select before opening the holdout','<p>I compared eight approaches across <strong>three chronological development folds</strong>. Neural models used five fixed seeds. Scalers were fitted on training data, target windows respected split boundaries, and the final 96 hours remained separate from model selection.</p><p>The selection rule was mean CV WAPE across carts and orders. It chose the <strong>168-hour seasonal baseline at 13.93%</strong>.</p>'+ranking_table),
('holdout','The final evaluation','<p>The selected baseline reached <strong>9.80% carts WAPE</strong> and <strong>11.34% orders WAPE</strong> on the final holdout. That did not make it best on every target: Ridge had a lower carts WAPE of 8.90%, but a higher orders WAPE of 12.18%.</p><p>I kept the model chosen by the predefined CV rule. Changing the winner after looking at the final test would have undermined the evaluation boundary.</p>'),
('interpretation','What the Transformer taught me','<p>The Transformer’s mean CV WAPE was 17.67%. I kept the implementation, five-seed comparisons and ablations because they help explain why extra complexity did not earn its place on this short series. The ablation study used a lighter protocol, so its scores are interpreted within that study.</p>'),
('limits','Limits that matter','<p>Four weeks do not establish monthly, holiday or promotion behavior. The aggregated data also lacks price, stock and marketing context. Prediction intervals are empirical uncertainty estimates rather than guaranteed future coverage.</p><p>The conclusion belongs to this experiment. It does not show that seasonal rules always beat Transformers. AI-assisted debugging, review and language editing are disclosed in the repository.</p>')
],[('Model ranking CSV',GH+'/otto-demand-forecasting-dissertation/blob/main/artifacts/research/cv_model_ranking.csv'),('Experiment manifest',GH+'/otto-demand-forecasting-dissertation/blob/main/artifacts/research/experiment_manifest.json'),('CV and holdout metrics',GH+'/otto-demand-forecasting-dissertation/blob/main/artifacts/research/research_metrics_summary.csv'),('Experiment design',GH+'/otto-demand-forecasting-dissertation/blob/main/docs/EXPERIMENT_DESIGN.md')],'rees46-v2','REES46 V2')

